function cambiaStatoMenu(e,t){const n=document.getElementById("nav_sparisce");n.classList.add(e),window.setTimeout(()=>{t?n.classList.add("aperta"):n.classList.remove("aperta"),n.classList.remove(e)},400)}document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelector(".navbar-burger"),t=document.getElementById("nav_sparisce");e.addEventListener("click",function(){e.classList.toggle("quadrato"),t.classList.contains("aperta")?cambiaStatoMenu("scrollup",!1):cambiaStatoMenu("scrolldown",!0)})})